import{_ as d,o as n,c as r,a5 as h}from"./chunks/framework.Bf1r8NYr.js";const s=JSON.parse('{"title":"Thuật ngữ","description":"","frontmatter":{},"headers":[],"relativePath":"course/glossary.md","filePath":"course/glossary.md"}'),i={name:"course/glossary.md"};function u(a,t,o,c,g,l){return n(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="thuat-ngu" tabindex="-1">Thuật ngữ <a class="header-anchor" href="#thuat-ngu" aria-label="Permalink to &quot;Thuật ngữ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Thuật ngữ</th><th>Định nghĩa ngắn</th></tr></thead><tbody><tr><td>ALCOA+</td><td>Các nguyên tắc bảo đảm tính toàn vẹn dữ liệu.</td></tr><tr><td>CDISC</td><td>Hệ tiêu chuẩn dữ liệu cho nghiên cứu và thử nghiệm lâm sàng.</td></tr><tr><td>CDE</td><td>Phần tử dữ liệu chung được định nghĩa để dùng nhất quán.</td></tr><tr><td>CRF</td><td>Biểu mẫu thu thập dữ liệu nghiên cứu.</td></tr><tr><td>Data dictionary</td><td>Tài liệu định nghĩa biến, kiểu dữ liệu, đơn vị và giá trị hợp lệ.</td></tr><tr><td>DMP</td><td>Kế hoạch quản lý dữ liệu trong toàn bộ vòng đời nghiên cứu.</td></tr><tr><td>DMSP</td><td>Kế hoạch quản lý và chia sẻ dữ liệu.</td></tr><tr><td>DUA</td><td>Thỏa thuận sử dụng dữ liệu.</td></tr><tr><td>EDC</td><td>Hệ thống thu thập dữ liệu điện tử.</td></tr><tr><td>eCRF</td><td>CRF điện tử.</td></tr><tr><td>FAIR</td><td>Findable, Accessible, Interoperable, Reusable.</td></tr><tr><td>FHIR</td><td>Tiêu chuẩn HL7 trao đổi dữ liệu y tế qua tài nguyên và API.</td></tr><tr><td>GDPR</td><td>Quy định bảo vệ dữ liệu chung của Liên minh châu Âu.</td></tr><tr><td>Metadata</td><td>Dữ liệu mô tả nguồn gốc, cấu trúc và ngữ cảnh của dữ liệu.</td></tr><tr><td>MNAR</td><td>Dữ liệu khuyết phụ thuộc vào chính giá trị bị khuyết.</td></tr><tr><td>OMOP CDM</td><td>Mô hình dữ liệu chung cho nghiên cứu quan sát.</td></tr><tr><td>Pseudonymisation</td><td>Thay định danh trực tiếp bằng mã nhưng vẫn có khả năng tái liên kết.</td></tr><tr><td>RBQM</td><td>Quản trị chất lượng dựa trên rủi ro.</td></tr><tr><td>REDCap</td><td>Nền tảng thu thập và quản lý dữ liệu nghiên cứu.</td></tr><tr><td>Reproducibility</td><td>Khả năng tái tạo kết quả bằng dữ liệu và quy trình đã mô tả.</td></tr><tr><td>audit trail</td><td>Dấu vết ghi lại ai sửa gì, khi nào và vì sao.</td></tr><tr><td>quasi-identifier</td><td>Tổ hợp thuộc tính có thể dùng để liên kết và phân biệt bản ghi.</td></tr><tr><td>k-anonymity</td><td>Mỗi tổ hợp quasi-identifier xuất hiện ít nhất k lần.</td></tr><tr><td>l-diversity</td><td>Yêu cầu đa dạng giá trị nhạy cảm trong mỗi nhóm k-anonymity.</td></tr><tr><td>differential privacy</td><td>Kỹ thuật thêm nhiễu có kiểm soát vào kết quả tổng hợp.</td></tr><tr><td>MCAR</td><td>Dữ liệu khuyết hoàn toàn ngẫu nhiên.</td></tr><tr><td>MAR</td><td>Dữ liệu khuyết có thể dự đoán từ dữ liệu đã quan sát.</td></tr><tr><td>imputation</td><td>Phương pháp xử lý hoặc ước lượng giá trị bị khuyết.</td></tr><tr><td>SDTM</td><td>Mô hình dữ liệu CDISC để nộp dữ liệu thử nghiệm lâm sàng.</td></tr><tr><td>GCP</td><td>Thực hành tốt trong nghiên cứu lâm sàng.</td></tr><tr><td>provenance</td><td>Thông tin về nguồn gốc, phiên bản và quá trình hình thành dữ liệu.</td></tr><tr><td>Safe Harbor</td><td>Phương pháp HIPAA loại bỏ 18 nhóm định danh theo danh sách quy định.</td></tr><tr><td>protocol</td><td>Đề cương mô tả nghiên cứu làm gì, vì sao và trên ai.</td></tr></tbody></table>',2)])])}const p=d(i,[["render",u]]);export{s as __pageData,p as default};
